local WORDS = {}
local function buildDict()
    for L, csv in pairs(DICT_LETTER) do
        local t = {}
        for w, tr in string.gmatch(csv, "([^,:]+):(%d)") do
            t[#t + 1] = { w = w, t = tonumber(tr) }
        end
        WORDS[L] = t
    end
end
buildDict()
DICT_LETTER = nil
math.randomseed(tick() % 100000)

-- state
local status = "starting..."
local lastWord = "-"
local lastTier = "-"
local lastPrompt = "-"
local filledFor = nil -- prefix..">"..word already filled this prompt
local rawPrev = nil
local adopted = nil -- stable prompt only (your typing never adopts)
local stableNow = false
local chosenFor = nil -- prefix.."#"..roundSeq already chosen for
local roundSeq = 0
local wasNil = true
local HARD = false -- hard-words-only mode (F2)

local function markUsed(word)
    if type(word) ~= "string" then return end
    local w = string.upper(word)
    if #w < 2 or #w > 15 then return end
    if not string.match(w, "^[A-Z]+$") then return end
    if used[w] then return end
    used[w] = true
    usedCount = usedCount + 1
    if usedCount <= 3000 then
        pcall(function() appendfile(USED_FILE, w .. "\n") end)
    end
end

-- creative pick: random word from the easiest tier that still has fresh
-- words (easy -> medium -> hard escalation); HARD mode uses tier 3 only.
local function pickWord(prefix, hardOnly)
    local L = string.sub(prefix, 1, 1)
    local list = WORDS[L]
    if not list then return nil end
    local tiers = hardOnly and { 3 } or { 1, 2, 3 }
    for _, tier in ipairs(tiers) do
        local cands = {}
        for _, e in ipairs(list) do
            if e.t == tier and string.sub(e.w, 1, #prefix) == prefix and not used[e.w] then
                cands[#cands + 1] = e.w
            end
        end
        if #cands > 0 then
            local w = cands[math.random(1, #cands)]
            return w, (tier == 1 and "easy" or (tier == 2 and "med" or "hard"))
        end
    end
    return nil
end

-- ---- UI reads --------------------------------------------------------------
local function readPrompt()
    if not lp then return nil end
    local pg = lp:FindFirstChild("PlayerGui")
    local sg = pg and pg:FindFirstChild("ScreenGui")
    local tb = sg and sg:FindFirstChild("TopBar")
    if not tb then return nil end
    local q = nil
    local parts = {}
    for _, d in ipairs(tb:GetDescendants()) do
        if d.ClassName == "TextLabel" then
            local ok, t = pcall(function() return d.Text end)
            if ok and type(t) == "string" and t ~= "" then
                if d.Name == "QuestionLabel" then
                    q = t
                elseif string.match(t, "^[A-Za-z]+$") and #t <= 3 then
                    local ap = d.AbsolutePosition
                    parts[#parts + 1] = { t = string.upper(t), x = ap and ap.X or 0 }
                end
            end
        end
    end
    if not q or not string.find(string.lower(q), "starting with", 1, true) then return nil end
    if #parts == 0 then return nil end
    table.sort(parts, function(a, b) return a.x < b.x end)
    -- prefer an explicit multi-letter prefix label, else join split singles
    local prefix = nil
    for _, p in ipairs(parts) do
        if #p.t > 1 then prefix = p.t break end
    end
    if not prefix then
        if #parts == 1 then
            prefix = parts[1].t
        else
            local s = {}
            for _, p in ipairs(parts) do
                if #p.t == 1 then s[#s + 1] = p.t end
            end
            if #s == 0 then return nil end
            prefix = table.concat(s)
        end
    end
    if prefix == "" or #prefix > 3 then return nil end
    return { letter = string.sub(prefix, 1, 1), prefix = prefix, q = q }
end

local function chatWindows()
    local cg = game:FindFirstChild("CoreGui")
    if not cg then return nil end
    for _, c in ipairs(cg:GetChildren()) do
        if c.Name == "ExperienceChat" then return c end
    end
    return nil
end

-- my word visible in chat under my name?
local function observeChat()
    local ec = chatWindows()
    if not ec then return end
    local me = lp and lp.Name or ""
    for _, d in ipairs(ec:GetDescendants()) do
        if d.ClassName == "TextLabel" and d.Name == "BodyText" then
            local ok, t = pcall(function() return d.Text end)
            if ok and type(t) == "string" then
                -- single words, tolerating trailing punctuation ("EEL!", "oh...")
                local w = string.match(t, "^%s*([A-Za-z]+)[^A-Za-z]*$")
                if w and #w >= 2 and #w <= 15 then markUsed(w) end
            end
        end
    end
end

local function chatHasMine(word)
    if not lp then return false end
    local ec = chatWindows()
    if not ec then return false end
    local want = string.lower(word)
    local desc = ec:GetDescendants()
    for i, d in ipairs(desc) do
        if d.ClassName == "TextLabel" and d.Name == "BodyText" then
            local ok, t = pcall(function() return d.Text end)
            if ok and type(t) == "string" and string.lower(t) == want then
                return true
            end
        end
        if i > 600 then break end
    end
    return false
end

local function fillWord(word, prefix)
    task.spawn(function()
        local alive = function() return _G.__SPRINT_GEN == MY_GEN end
        if not alive() then return end
        -- contract: YOU focus the chat box first (click it or type a letter).
        -- clear any partial typing (12 backspaces; no-op if box is empty),
        -- then type slowly so the game drops nothing.
        for k = 1, 12 do
            if not alive() then return end
            pcall(function() keypress(8) end)
            task.wait(0.03)
        end
        if not alive() then return end
        -- re-verify: same STABLE prompt still adopted (never fill mid-change)
        if not adopted or adopted.prefix ~= prefix then
            status = 'prompt moved, aborted'
            return
        end
        for k = 1, #word do
            if not alive() then return end
            pcall(function() keypress(string.byte(word, k)) end)
            task.wait(0.12)
        end
        filledFor = prefix .. '>' .. word
        status = 'filled ' .. word .. ' - Enter to send'
        print('[Sprint] filled: ' .. word)
    end)
end

