local panelBg = Drawing.new("Square")
panelBg.Filled = true
panelBg.Color = Color3.fromRGB(13, 20, 32)
panelBg.Transparency = 0.25
panelBg.Visible = false
local panelTitle = Drawing.new("Text")
panelTitle.Size = 15
panelTitle.Font = 11
panelTitle.Color = Color3.fromRGB(240, 244, 248)
panelTitle.Outline = true
panelTitle.Visible = false
local panelRows = {}
for i = 1, 5 do
    local t = Drawing.new("Text")
    t.Size = 13
    t.Font = 1
    t.Color = Color3.fromRGB(203, 213, 225)
    t.Outline = true
    t.Visible = false
    panelRows[i] = t
end
local function hidePanel()
    panelBg.Visible = false
    panelTitle.Visible = false
    for _, r in ipairs(panelRows) do r.Visible = false end
end

local view = { line1 = "...", line2 = "", solveTxt = "OFF" }

_G.__SprintState = function()
    return "solve=" .. tostring(SOLVE) .. " prompt=" .. lastPrompt
        .. " word=" .. lastWord .. " status=" .. status
        .. " loops=" .. HEALTH.loops .. " renders=" .. HEALTH.renders
        .. " keys=" .. HEALTH.keys .. " err=" .. HEALTH.err
        .. " gen=" .. tostring(_G.__SPRINT_GEN)
end

-- ---- main loop -------------------------------------------------------------
loadAll()
task.spawn(function()
    while running do
        if _G.__SPRINT_GEN ~= MY_GEN then break end
        HEALTH.loops = HEALTH.loops + 1
        local okLoop, errLoop = pcall(function()
            if not ensureServices() then task.wait(1.0) return end
            local p = readPrompt()
            local raw = p and p.prefix or "-"
            local settled = (raw == rawPrev)
            rawPrev = raw
            if settled then adopted = p end
            stableNow = settled
            observeChat()
            if adopted then
                if wasNil then
                    roundSeq = roundSeq + 1
                    wasNil = false
                end
                lastPrompt = adopted.prefix
                if not SOLVE then
                    status = "armed OFF (F6)"
                elseif not settled then
                    status = "typing hold..."
                else
                    local key = adopted.prefix .. "#" .. roundSeq
                    if chosenFor ~= key or used[lastWord]
                        or string.sub(lastWord, 1, #adopted.prefix) ~= adopted.prefix then
                        local w, tr = pickWord(adopted.prefix, HARD)
                        if w then
                            lastWord, lastTier, chosenFor = w, tr, key
                        else
                            lastWord, lastTier = "-", "-"
                        end
                    end
                    if lastWord ~= "-" then
                        if filledFor == adopted.prefix .. ">" .. lastWord then
                            status = "filled " .. lastWord .. " - Enter to send"
                        else
                            status = "F5 completes: " .. lastWord
                        end
                    else
                        status = (HARD and "no HARD words for " or "no fresh word for ")
                            .. adopted.prefix
                    end
                end
            else
                wasNil = true
                lastPrompt = "-"
                filledFor = nil
                if not SOLVE then status = "armed OFF (F6)"
                else status = "waiting for prompt..." end
            end
            view.line1 = lastPrompt .. " -> " .. lastWord
                .. (lastTier ~= "-" and " [" .. lastTier .. "]" or "")
            view.line2 = status
            view.solveTxt = SOLVE and (HARD and "ON:HARD" or "ON") or "OFF"
            task.wait(0.5)
        end)
        if not okLoop then
            HEALTH.err = tostring(errLoop):sub(1, 100)
            print("[Sprint] loop error: " .. tostring(errLoop))
            task.wait(0.5)
        end
    end
end)

-- ---- renderer --------------------------------------------------------------
task.spawn(function()
    while running do
        if _G.__SPRINT_GEN ~= MY_GEN then break end
        HEALTH.renders = HEALTH.renders + 1
        if not VISIBLE then
            hidePanel()
        else
            local vpx, vpy = 1600, 900
            local ws = workspace
            local cam = ws and ws.CurrentCamera
            local vs = cam and cam.ViewportSize
            if vs and vs.X and vs.X > 100 then vpx = vs.X end
            if vs and vs.Y and vs.Y > 100 then vpy = vs.Y end
            local px, py = vpx - 304, 84
            panelBg.Position = Vector2.new(px, py)
            panelTitle.Text = "Sprint [" .. view.solveTxt .. "]"
            panelTitle.Position = Vector2.new(px + 10, py + 6)
            panelTitle.Visible = true
            local rows
            if COMPACT then
                panelBg.Size = Vector2.new(288, 56)
                panelBg.Visible = true
                rows = { view.line1, string.sub(view.line2, 1, 40) }
            else
                panelBg.Size = Vector2.new(288, 142)
                panelBg.Visible = true
                rows = {
                    view.line1,
                    "Solve: " .. (SOLVE and "ON" or "OFF") .. " (" .. keyName(BINDS.SOLVE) .. ")"
                        .. (HARD and " HARD [" .. keyName(BINDS.HARD) .. "]" or ""),
                    string.sub(view.line2, 1, 40),
                    "used " .. usedCount .. " | F1 rebind keys",
                    "F5 fill F3 skip F4 reset",
                }
            end
            local y = py + 28
            for i = 1, 5 do
                if rows[i] then
                    panelRows[i].Text = rows[i]
                    panelRows[i].Position = Vector2.new(px + 10, y)
                    panelRows[i].Visible = true
                    y = y + 21
                else
                    panelRows[i].Visible = false
                end
            end
        end
        task.wait(0.08)
    end
    hidePanel()
end)

-- ---- input (keyboard-driven panel: binds rebindable, persisted) ------------
task.spawn(function()
    local held = {}
    local ORDER = { "SOLVE", "COMPLETE", "SKIP", "HARD", "HIDE", "RESET", "COMPACT" }
    while running do
        if _G.__SPRINT_GEN ~= MY_GEN then break end
        -- F1: rebind mode (fixed key, never rebound itself)
        local f1 = iskeypressed(112)
        if f1 and not held[112] then
            held[112] = true
            if capturing then
                capturing = nil
                toast("rebind cancelled")
            else
                capturing = REBIND_ORDER[1]
                capArmed = false
                capT0 = tick()
                toast("press key for " .. capturing)
            end
        elseif not f1 then
            held[112] = false
        end
        if capturing then
            local anyDown = false
            for _, c in ipairs(SCANCODES) do
                if iskeypressed(c) then anyDown = true break end
            end
            if not anyDown then capArmed = true end
            if capArmed then
                for _, c in ipairs(SCANCODES) do
                    if iskeypressed(c) then
                        BINDS[capturing] = c
                        saveCfg()
                        print("[Sprint] bind " .. capturing .. " -> " .. keyName(c))
                        toast(capturing .. " = " .. keyName(c))
                        local nextAct = nil
                        for i, a in ipairs(REBIND_ORDER) do
                            if a == capturing then nextAct = REBIND_ORDER[i + 1] break end
                        end
                        capturing = nextAct
                        capArmed = false
                        capT0 = tick()
                        if capturing then toast("press key for " .. capturing)
                        else toast("rebind done") end
                        break
                    end
                end
            end
            if capturing and tick() - capT0 > 12 then
                capturing = nil
                toast("rebind timed out")
            end
        else
            for _, act in ipairs(ORDER) do
                local code = BINDS[act]
                if code ~= 112 then -- F1 reserved for rebind mode
                    local down = iskeypressed(code)
                if down and not held[code] then
                    held[code] = true
                    HEALTH.keys = HEALTH.keys + 1
                    if act == "SOLVE" then
                        SOLVE = not SOLVE
                        _G.__SPRINT_SOLVE = SOLVE
                        print("[Sprint] solver: " .. (SOLVE and "ON" or "OFF"))
                        toast("solver " .. (SOLVE and "ON" or "OFF"))
                    elseif act == "COMPLETE" then
                        if not SOLVE then
                            toast("solver first")
                        elseif not adopted then
                            toast("no prompt")
                        elseif filledFor == adopted.prefix .. ">" .. lastWord then
                            toast("already filled")
                        elseif lastWord == "-" then
                            toast("no suggestion yet")
                        else
                            print("[Sprint] completing: " .. lastWord)
                            fillWord(lastWord, adopted.prefix)
                        end
                    elseif act == "HIDE" then
                        VISIBLE = not VISIBLE
                        print("[Sprint] overlay: " .. tostring(VISIBLE))
                    elseif act == "RESET" then
                    used = {}
                    usedCount = 0
                    adopted = nil
                    rawPrev = nil
                    filledFor = nil
                    chosenFor = nil
                    lastWord = "-"
                    lastTier = "-"
                        print("[Sprint] memory reset")
                        toast("memory reset")
                    elseif act == "COMPACT" then
                        COMPACT = not COMPACT
                        saveCfg()
                        print("[Sprint] compact: " .. tostring(COMPACT))
                    elseif act == "SKIP" then
                        if lastWord ~= "-" then
                            markUsed(lastWord)
                            filledFor = nil
                            print("[Sprint] skipped: " .. lastWord)
                            toast("skipped " .. lastWord)
                        end
                    elseif act == "HARD" then
                        HARD = not HARD
                        saveCfg()
                        print("[Sprint] hard-only: " .. tostring(HARD))
                        toast("hard words " .. (HARD and "ONLY" or "off"))
                    end
                elseif not down then
                    held[code] = false
                end
                end -- code ~= 112
            end
        end
        task.wait(0.08)
    end
end)

print("[Sprint] Keys: F6 solve F5 fill F3 skip F2 hard F7 hide F4 reset F8 view F1 rebind")
